using System;
using System.Collections.Generic;
using System.Linq;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
namespace Aurora {
public sealed class TestPhaseFeature {
    public string Id,Pt,En,ReasonPt,ReasonEn;public string[] Titles;
    public string Name{get{return L.T(Pt,En);}}public string Reason{get{return L.T(ReasonPt,ReasonEn);}}
}
public static class ReleaseQualification {
    public static readonly TestPhaseFeature[] Features={
        Item("ouo-update","Atualização do próprio OuO","OuO self-update","Consulta, canais e integridade possuem testes. Troca e recuperação entre duas distribuições completas ainda precisam de ensaio.","Queries, channels and integrity have tests. Switching and recovering between two complete distributions still need testing.","OuO updates"),
        Item("driver-cleanup","Limpeza de vídeo e áudio","Video and audio cleanup","Inventário, escopo e proteções possuem testes; remoção, reinicialização e reinstalação em hardware físico ainda precisam de validação.","Inventory, scope and protections have tests; removal, reboot and reinstall on physical hardware still need validation.","Video and audio driver cleanup"),
        Item("sensor-install","Instalação do driver de sensores","Sensor driver installation","Instalador oficial 2.2.0 conferido por hash e assinatura; primeira instalação e cancelamento de UAC variam por sistema e precisam de ensaio próprio.","Official 2.2.0 installer checked by hash and signature; first installation and UAC cancellation vary by system and need dedicated testing.","Sensor access setup","Sensor engine"),
        Item("clone","Clonagem e inicialização","Cloning and boot","Cópia e GPT verificadas em discos virtuais; inicialização da cópia e dispositivos SATA/NVMe/USB ainda precisam de ensaio.","Copy and GPT verified on virtual disks; booting the clone and SATA/NVMe/USB devices still need testing.","Direct disk cloning","System image"),
        Item("account","Recuperação de conta","Account recovery","Cópias e formato do Registro foram verificados. A entrada na conta de um Windows recuperado ainda precisa de validação.","Registry copies and format were verified. Signing in to a recovered Windows account still needs validation.","Recover an account in another Windows","Local account recovery"),
        Item("boot","F8 e recuperação","F8 and recovery","A alternância e a reinicialização precisam de um Windows instalado; o Sandbox não oferece BCD convencional.","Switching and rebooting need an installed Windows; Sandbox does not expose a conventional BCD.","F8 and recovery environment"),
        Item("restore","Ponto de restauração","Restore point","A agenda foi validada. Criação efetiva e restauração dependem da Proteção do Sistema e de ensaio adicional.","Scheduling was verified. Actual creation and rollback depend on System Protection and further testing.","Restore point","Daily schedules"),
        Item("office","Instalação e remoção do Office","Office installation and removal","A ferramenta e os planos são conferidos. Edições, conflitos MSI/Click-to-Run e instalações reais ainda não têm homologação ampla.","Tool and plans are checked. Editions, MSI/Click-to-Run conflicts and real installs are not broadly qualified.","Automatic download and installation","Official tool & execution"),
        Item("drivers","Instalação de drivers","Driver installation","Busca e correspondência foram verificadas. Instalação, reinicialização e versão final exigem hardware correspondente.","Search and matching were checked. Installation, reboot and final version need matching hardware.","Available updates","Additional driver sources","Downloaded driver packs"),
        Item("cloud","Download e remoção do OneDrive","OneDrive download and removal","Proteções verificadas em arquivos controlados. Download e remoção em contas pessoais/empresariais ainda estão em validação.","Guards checked with controlled files. Download and removal for personal/business accounts are still being validated.","OneDrive"),
        Item("cloud-storage","Análise de armazenamento em nuvem","Cloud storage analysis","Login, arquivos e cotas por serviço foram consultados em uma conta pessoal Google. Outras contas, OneDrive e cenários de falha ainda precisam de validação ampliada.","Sign-in, files and service quotas were queried on one personal Google account. Other accounts, OneDrive and failure scenarios still need broader validation.","Analyze Google Drive and OneDrive"),
        Item("memory","Gerenciamento de memória","Memory management","API e critérios verificados em auxiliares próprios. Acompanhamento prolongado com aplicativos reais ainda está em validação.","API and eligibility checked with owned workers. Prolonged observation with real apps is still being validated.","Automatic memory reclaim","Memory & performance"),
        Item("printing","Recuperação de impressão","Printer recovery","Execução e proteções verificadas em cenários controlados. Impressoras físicas, preferências e reinstalação exigem teste com o equipamento.","Execution and guards checked in controlled cases. Physical printers, preferences and reinstall need testing with the device.","Print queue","Selected printer"),
        Item("installers","Instalação e remoção de programas","Program installation and removal","Inventário e fluxos foram verificados em cenários controlados. Instalação, atualização e remoção reais por WinGet/Chocolatey/Scoop, MSI e Store ainda precisam de ensaios por pacote e versão do Windows.","Inventory and flows checked in controlled cases. Real WinGet/Chocolatey/Scoop, MSI and Store installation, update and removal still need package- and Windows-specific trials.","Install with WinGet","Application and game runtimes","Installed programs"),
        Item("tweaks","Tweaks e configurações avançadas","Tweaks and advanced settings","Seleção, consulta, backup e restauração foram verificados. O efeito de cada ajuste, remoção e alteração de energia ou segurança ainda precisa de ensaio na edição e versão correspondentes.","Selection, queries, backup and restore were checked. Each setting, removal and power or security change still needs testing on the corresponding Windows edition and release.","Choose settings","Advanced power and storage features","BitLocker","Components and automatic installation"),
        Item("cleanup","Limpeza de arquivos e rastros","File and remnant cleanup","Proteções e exclusão de arquivos próprios foram verificadas. Caches e rastros de cada programa real ainda precisam de validação; revise os itens encontrados antes de excluir.","Guards and deletion of owned files were checked. Each real program's caches and remnants still need validation; review findings before deleting.","Temporary files and caches","Traces to review"),
        Item("antimalware","Integração com antimalware","Antimalware integration","As consultas de processos e os fluxos foram verificados. Detecção de ameaças reais e integração com cada versão dos motores externos ainda precisam de homologação.","Process queries and flows were checked. Detection of real threats and integration with each external engine version still need qualification.","Malware scan"),
        Item("disk-map","Mapa de disco","Disk map","O índice NTFS foi verificado em discos virtuais. Tempo de leitura e completude em unidades físicas grandes ainda dependem de auditoria com administrador.","NTFS indexing was verified on virtual disks. Speed and completeness on large physical drives still need an administrator audit.","Disk space map"),
        Item("repair","Reparos do sistema","System repairs","Execução e recuperação de falhas precisam de testes adicionais em instalações correspondentes. Consulte os detalhes antes de aplicar.","Execution and failure recovery need more testing on corresponding installations. Read details before applying.","SFC","DISM • online","DISM / SFC • offline","CHKDSK","Reset Windows Update","Local policies"),
        Item("features","Recursos opcionais","Optional features","Consulta e interface verificadas. Instalação/remoção e reinicialização variam por edição e precisam de ensaio específico.","Queries and UI were checked. Install/removal and reboot vary by edition and need dedicated testing.","Optional Windows features","Hyper-V",".NET Framework"),
        Item("upgrade","Atualização de versão do Windows","Windows version upgrade","Checagens disponíveis; instalação, migração e contornos de requisitos permanecem em testes e não garantem oferta pelo Windows Update.","Checks are available; installation, migration and requirement workarounds remain in testing and cannot guarantee a Windows Update offer.","Select a reference release","Windows 7 to Windows 10 via media","Next step • Windows 10 to Windows 11"),
        Item("registry","Limpeza ampliada do Registro","Extended Registry cleanup","Backups e rechecagem verificados em cenários controlados. A validade de referências de aplicativos reais precisa de avaliação individual.","Backups and rechecks verified in controlled cases. References from real applications need individual review.","Extended Registry analysis"),
        Item("display","Alteração de resolução","Display mode changes","Leitura e temporizador verificados; troca/reversão em monitores e drivers diversos ainda requerem validação.","Readout and timer checked; switching/reverting across displays and drivers still needs validation.","Display resolution"),
        Item("browser","Políticas de navegadores","Browser policies","Regras verificadas em cenários controlados. Efeito com DoH, perfis e diferentes navegadores depende de homologação adicional.","Rules verified in controlled cases. DoH, profiles and different browsers need additional qualification.","Sites you blocked","Automatic browser protection","Managed blocked page extension","Security extensions in your browsers"),
        Item("dns","Aplicação de DNS","DNS changes","Aplicação, leitura e restauração passaram em uma compilação anterior no Sandbox. A compilação atual e cenários com VPN, vários adaptadores e DNS seguro ainda precisam de validação administrativa.","Apply, readback and restore passed on an earlier Sandbox build. The current build and VPN, multiple-adapter and secure-DNS scenarios still need administrative validation.","Connection & profile")
    };
    static TestPhaseFeature Item(string id,string pt,string en,string reasonPt,string reasonEn,params string[] titles){return new TestPhaseFeature{Id=id,Pt=pt,En=en,ReasonPt=reasonPt,ReasonEn=reasonEn,Titles=titles};}
    public static TestPhaseFeature ForTitle(string title){string english=UiLanguage.English(title);return Features.FirstOrDefault(x=>x.Titles.Any(t=>String.Equals(t,english,StringComparison.OrdinalIgnoreCase)))??(english.StartsWith("DISM",StringComparison.OrdinalIgnoreCase)?Features.First(x=>x.Id=="repair"):null);}
}
// No PropertyDescriptor/global event table: discarded page labels must be collectable.
public sealed class ResultTextBlock:TextBlock {
    public Func<string,Brush> ResolveTone;
    static ResultTextBlock(){TextProperty.OverrideMetadata(typeof(ResultTextBlock),new FrameworkPropertyMetadata("",TextChanged));}
    static void TextChanged(DependencyObject sender,DependencyPropertyChangedEventArgs e){var block=(ResultTextBlock)sender;if(block.ResolveTone!=null)block.Foreground=block.ResolveTone(block.Text);}
}
public partial class MainWindow {
    void ApplyQualificationTheme(){Application.Current.Resources["OuO.TestPhaseInk"]=dark?Color("#F4C873"):Color("#7B4D00");}
    void AddTestPhaseNotice(Panel parent,string title){var feature=ReleaseQualification.ForTitle(title);if(feature==null)return;var text=new TextBlock{Text=T("Recurso em fase de testes","Feature in testing")+"\n"+feature.Reason,TextWrapping=TextWrapping.Wrap,FontSize=12,Margin=new Thickness(10,8,10,8)};text.SetResourceReference(TextBlock.ForegroundProperty,"OuO.TestPhaseInk");var border=new Border{Tag="OuO.TestPhase:"+feature.Id,Child=text,CornerRadius=new CornerRadius(6),BorderThickness=new Thickness(1),Margin=new Thickness(0,0,0,10)};border.SetResourceReference(Border.BorderBrushProperty,"OuO.TestPhaseInk");System.Windows.Automation.AutomationProperties.SetName(border,T("Recurso em fase de testes: ","Feature in testing: ")+feature.Name);parent.Children.Add(border);}
}
}
